      out.write("\n");
      out.write("<script>\n");
      out.write("const CTX = '");
      out.print( request.getContextPath() );
      out.write("';\n");
      out.write("let idAvailable = false;\n");
      out.write("\n");
      out.write("/* ── 아이디 중복 확인 (AJAX) ── */\n");
      out.write("function checkIdAvail() {\n");
      out.write("    const id = document.getElementById('memberId').value.trim();\n");
      out.write("    const msg = document.getElementById('idMsg');\n");
      out.write("\n");
      out.write("    if (!id) { setMsg(msg, '아이디를 입력하세요.', false); return; }\n");
      out.write("    if (!/^[a-zA-Z0-9]{4,20}$/.test(id)) {\n");
      out.write("        setMsg(msg, '4~20자 영문·숫자만 입력하세요.', false);\n");
      out.write("        idAvailable = false; return;\n");
      out.write("    }\n");
      out.write("\n");
      out.write("    fetch(CTX + '/member/idCheck.jsp?memberId=' + encodeURIComponent(id))\n");
      out.write("        .then(r => r.json())\n");
      out.write("        .then(data => {\n");
      out.write("            idAvailable = data.available;\n");
      out.write("            setMsg(msg, data.message, data.available);\n");
      out.write("        })\n");
      out.write("        .catch(() => setMsg(msg, '중복 확인 중 오류가 발생했습니다.', false));\n");
      out.write("}\n");
      out.write("\n");
      out.write("function resetIdCheck() {\n");
      out.write("    idAvailable = false;\n");
      out.write("    const msg = document.getElementById('idMsg');\n");
      out.write("    msg.textContent = '';\n");
      out.write("    msg.className = 'field-msg';\n");
      out.write("}\n");
      out.write("\n");
      out.write("/* ── 비밀번호 강도 ── */\n");
      out.write("function updatePwStrength(pw) {\n");
      out.write("    const bar = document.getElementById('pwStrengthBar');\n");
      out.write("    const msg = document.getElementById('pwMsg');\n");
      out.write("    let score = 0;\n");
      out.write("    if (pw.length >= 8)  score++;\n");
      out.write("    if (/[A-Z]/.test(pw)) score++;\n");
      out.write("    if (/[0-9]/.test(pw)) score++;\n");
      out.write("    if (/[^A-Za-z0-9]/.test(pw)) score++;\n");
      out.write("\n");
      out.write("    const levels = [\n");
      out.write("        { w:'25%',  c:'#e05252', t:'' },\n");
      out.write("        { w:'50%',  c:'#e09852', t:'약함' },\n");
      out.write("        { w:'75%',  c:'#e5d44e', t:'보통' },\n");
      out.write("        { w:'100%', c:'#52c07a', t:'강함' }\n");
      out.write("    ];\n");
      out.write("    if (pw.length === 0) { bar.style.width='0'; msg.textContent=''; return; }\n");
      out.write("    const lv = levels[Math.min(score - 1, 3)] || levels[0];\n");
      out.write("    bar.style.width = lv.w;\n");
      out.write("    bar.style.background = lv.c;\n");
      out.write("    setMsg(msg, lv.t ? `비밀번호 강도: ");
