      out.write("    const pw2 = document.getElementById('memberPw2').value;\n");
      out.write("    const msg = document.getElementById('pw2Msg');\n");
      out.write("    if (!pw2) { msg.textContent=''; return; }\n");
      out.write("    if (pw === pw2) setMsg(msg, '비밀번호가 일치합니다.', true);\n");
      out.write("    else            setMsg(msg, '비밀번호가 일치하지 않습니다.', false);\n");
      out.write("}\n");
      out.write("\n");
      out.write("/* ── 다음(카카오) 우편번호 검색 ── */\n");
