      out.write("    const roadAddr   = document.getElementById('roadAddr').value.trim();\n");
      out.write("    const detailAddr = document.getElementById('detailAddr').value.trim();\n");
      out.write("\n");
      out.write("    if (!id || !/^[a-zA-Z0-9]{4,20}$/.test(id)) {\n");
      out.write("        alert('아이디는 4~20자 영문·숫자로 입력하세요.'); form.memberId.focus(); return false;\n");
      out.write("    }\n");
      out.write("    if (!idAvailable) {\n");
      out.write("        alert('아이디 중복 확인을 해주세요.'); form.memberId.focus(); return false;\n");
      out.write("    }\n");
      out.write("    if (pw.length < 8) {\n");
      out.write("        alert('비밀번호는 8자 이상 입력하세요.'); form.memberPw.focus(); return false;\n");
